export default function (pi: any) {
  pi.registerTool({
    name: "dump",
    label: "Dump",
    description: "Large local result to exercise native automatic rollover",
    parameters: { type: "object", properties: {} },
    async execute() {
      return { content: [{ type: "text", text: "x".repeat(600000) }], details: {} };
    },
  });
}

import * as fs from "node:fs";
import { randomBytes } from "node:crypto";
export default function (pi: any) {
  pi.registerCommand("eq-ctxedit", {
    description: "harness: append a context_edit for the last result of a tool (second word `null` omits it, else the replacement text)",
    handler: async (args: string, ctx: any) => {
      const [tool, ...rest] = args.trim().split(/\s+/);
      const replacement = rest.join(" ");
      const file = ctx.sessionManager.getSessionFile();
      const entries = ctx.sessionManager.getEntries();
      const target = [...entries].reverse().find((e: any) => e.type === "message" && e.message?.role === "toolResult" && e.message.toolName === tool);
      if (!target) throw new Error("eq-ctxedit: no " + tool + " result");
      const entry = {
        type: "context_edit",
        id: randomBytes(4).toString("hex"),
        parentId: ctx.sessionManager.getLeafId(),
        timestamp: new Date().toISOString(),
        targetId: target.id,
        replacement: replacement === "null" ? null : { content: [{ type: "text", text: replacement }] },
      };
      fs.appendFileSync(file, JSON.stringify(entry) + "\n");
    },
  });
}
